sys_script_include.script:
var VendorDataUtils = Class.create();
VendorDataUtils.prototype = {
    initialize: function() {
    },


	/**
	 * Return true if there is a Scheduled Import for 
	 * this data source with a run start after @relativeTo.
	 */
	hasScheduledImportAfter: function(scope, dataSourceName, active, gdtRelativeTo ){
		var dataSourceSysId = this._getDataSourceSysId(scope, dataSourceName);
		var gr = new GlideRecord("scheduled_import_set");
		var query = "sys_scope=" + scope;
		query += "^data_source=" + dataSourceSysId;
		if(active) query += "^active=true"; 
		query += "^run_start>" + gdtRelativeTo;
		gr.addEncodedQuery(query);
		gr.setLimit(1);
		gr.query();
		return gr.hasNext();
	},

	deleteDataSourceAttachments: function(scope, dataSourceName){
		var result = {"num_deleted":0};
		var ds_sys_id = this._getDataSourceSysId(scope, dataSourceName);
		if(!ds_sys_id) throw "No data source named " + dataSourceName + " in scope " + scope + ".";
		var gsa = new GlideSysAttachment();
		var gr = new GlideRecord("sys_attachment");
		gr.addQuery("table_name", "sys_data_source");
		gr.addQuery("table_sys_id", ds_sys_id);
		gr.query();
		while(gr.next()) {
			gsa.deleteAttachment(gr.getValue("sys_id"));
			result["num_deleted"]++;
		}
		return result;
	},

	shiftAttachments(fromDataSourceName, toDataSourceName, limit) {
		var from_sys_id = this._getDataSourceSysId(scope, fromDataSourceName);
		var to_sys_id = this._getDataSourceSysId(scope, toDataSourceName);
		var gsa = new GlideSysAttachment();

		//copy(String sourceTable, String sourceID, String targetTable, String targetID)
	},

	createScheduledImport: function(){

	},

	/**
	 * Given application scope (sys_id) and the name of 
	 * a Data Source, return Data source's sys_id, or null.
	 */
	_getDataSourceSysId: function(scope, name) {
		var result = null;
		var gr = new GlideRecord("sys_data_source");
		gr.addQuery("sys_scope", scope);
		gr.addQuery("name", name);
		gr.setLimit(1);
		gr.query();
		if(gr.next()) result = gr.getValue("sys_id");
		return result;
	},

    type: 'VendorDataUtils'
};
